// Package swiftrt is the runtime support library for Go code generated by swift2go.
package swiftrt

import (
	"cmp"
	"fmt"
	"math"
	"reflect"
	"slices"
	"strconv"
	"strings"
)

// Integer is every Go integer type a Swift integer maps to.
type Integer interface {
	~int | ~int8 | ~int16 | ~int32 | ~int64 | ~uint | ~uint8 | ~uint16 | ~uint32 | ~uint64
}

// Unsupported marks a construct swift2go cannot translate yet; reaching it at runtime panics.
func Unsupported[T any](what string) T {
	panic("swift2go: unsupported " + what)
}

// Trap reports a Swift runtime trap.
func Trap(msg string) { panic("swift trap: " + msg) }

func overflow() { Trap("arithmetic overflow") }

func bounds[T Integer]() (min, max int64, unsigned bool, umax uint64) {
	var z T
	switch any(z).(type) {
	case int, int64:
		return math.MinInt64, math.MaxInt64, false, 0
	case int8:
		return math.MinInt8, math.MaxInt8, false, 0
	case int16:
		return math.MinInt16, math.MaxInt16, false, 0
	case int32:
		return math.MinInt32, math.MaxInt32, false, 0
	case uint8:
		return 0, 0, true, math.MaxUint8
	case uint16:
		return 0, 0, true, math.MaxUint16
	case uint32:
		return 0, 0, true, math.MaxUint32
	default:
		return 0, 0, true, math.MaxUint64
	}
}

// Add is Swift's trapping `+`.
func Add[T Integer](a, b T) T {
	r := a + b
	if (r > a) != (b > 0) && b != 0 {
		overflow()
	}
	return r
}

// Sub is Swift's trapping `-`.
func Sub[T Integer](a, b T) T {
	r := a - b
	if (r < a) != (b > 0) && b != 0 {
		overflow()
	}
	return r
}

// Mul is Swift's trapping `*`.
func Mul[T Integer](a, b T) T {
	if a == 0 || b == 0 {
		return 0
	}
	r := a * b
	if r/b != a {
		overflow()
	}
	_, _, unsigned, _ := bounds[T]()
	if !unsigned && (a < 0) != (b < 0) && r > 0 {
		overflow()
	}
	return r
}

// Some wraps a value as a present optional.
func Some[T any](v T) *T { return new(v) }

// Force is Swift's postfix `!` on a value optional.
func Force[T any](p *T) *T {
	if p == nil {
		Trap("unexpectedly found nil while unwrapping an Optional value")
	}
	return p
}

// ForceRef is Swift's postfix `!` on a reference optional.
func ForceRef[T any](v T) T {
	if isNil(v) {
		Trap("unexpectedly found nil while unwrapping an Optional value")
	}
	return v
}

func isNil(v any) bool {
	if v == nil {
		return true
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Pointer, reflect.Map, reflect.Slice, reflect.Func, reflect.Interface:
		return rv.IsNil()
	}
	return false
}

// Coalesce is Swift's `??`.
func Coalesce[T any](p *T, d T) T {
	if p == nil {
		return d
	}
	return *p
}

// CoalesceFunc is Swift's `??` with a right side that runs only when p is nil.
func CoalesceFunc[T any](p *T, d func() T) T {
	if p == nil {
		return d()
	}
	return *p
}

// Equal is Swift `==` for values Go cannot compare with `==` (slices, maps, optionals).
func Equal[T any](a, b T) bool { return equalValues(reflect.ValueOf(a), reflect.ValueOf(b)) }

var substringType = reflect.TypeFor[Substring]()

// SwiftEqualer is a type that declares its own `==`.
type SwiftEqualer interface{ SwiftEqual(other any) bool }

// customEqual returns v's own `==`. A pointer to a struct is an Optional, whose == unwraps it first.
func customEqual(v reflect.Value) (SwiftEqualer, bool) {
	if !v.CanInterface() {
		return nil, false
	}
	if v.Kind() == reflect.Pointer {
		if _, class := v.Interface().(SwiftClass); !class {
			return nil, false
		}
	}
	eq, ok := v.Interface().(SwiftEqualer)
	return eq, ok
}

// equalValues is reflect.DeepEqual except that Substrings compare by content, as Swift's do.
func equalValues(a, b reflect.Value) bool {
	if !a.IsValid() || !b.IsValid() {
		return a.IsValid() == b.IsValid()
	}
	if a.Type() == substringType && b.Type() == substringType {
		return a.Interface().(Substring).String() == b.Interface().(Substring).String()
	}
	if eq, ok := customEqual(a); ok {
		if a.Kind() == reflect.Pointer && (a.IsNil() || b.Kind() == reflect.Pointer && b.IsNil()) {
			return a.IsNil() && b.Kind() == reflect.Pointer && b.IsNil()
		}
		return b.CanInterface() && eq.SwiftEqual(b.Interface())
	}
	switch a.Kind() {
	case reflect.Slice, reflect.Array:
		if a.Len() != b.Len() {
			return false
		}
		for i := 0; i < a.Len(); i++ {
			if !equalValues(a.Index(i), b.Index(i)) {
				return false
			}
		}
		return true
	case reflect.Pointer, reflect.Interface:
		if a.IsNil() || b.IsNil() {
			return a.IsNil() && b.IsNil()
		}
		return equalValues(a.Elem(), b.Elem())
	case reflect.Struct:
		// A struct's fields compare one by one, so a field whose type declares its own == uses it, as
		// Swift's synthesized == does. A struct with unexported fields is a runtime type and compares
		// deeply.
		if a.Type() != b.Type() {
			return false
		}
		if exportedFields(a.Type()) {
			for i := range a.NumField() {
				if !equalValues(a.Field(i), b.Field(i)) {
					return false
				}
			}
			return true
		}
	}
	return reflect.DeepEqual(a.Interface(), b.Interface())
}

func exportedFields(t reflect.Type) bool {
	for i := range t.NumField() {
		if !t.Field(i).IsExported() {
			return false
		}
	}
	return true
}

// Clone copies a slice or map so a Swift `var` binding gets its own value.
func Clone[T any](v T) T {
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Slice:
		if rv.IsNil() {
			return v
		}
		out := reflect.MakeSlice(rv.Type(), rv.Len(), rv.Len())
		reflect.Copy(out, rv)
		return out.Interface().(T)
	case reflect.Map:
		if rv.IsNil() {
			return v
		}
		out := reflect.MakeMapWithSize(rv.Type(), rv.Len())
		for _, k := range rv.MapKeys() {
			out.SetMapIndex(k, rv.MapIndex(k))
		}
		return out.Interface().(T)
	}
	return v
}

// Concat is Swift `+` on arrays.
func Concat[T any](a, b []T) []T {
	out := make([]T, 0, len(a)+len(b))
	return append(append(out, a...), b...)
}

// ownDescription marks a type whose Description method is a member of its own, not a
// CustomStringConvertible witness, which printing must not use.
type ownDescription interface{ SwiftOwnDescription() }

// ownDebugDescription marks a type whose DebugDescription method is a member of its own.
type ownDebugDescription interface{ SwiftOwnDebugDescription() }

func ownsDescription(v any) bool {
	_, own := v.(ownDescription)
	return own
}

// Describer is a Swift type conforming to CustomStringConvertible.
type Describer interface{ Description() string }

// DebugDescriber is a Swift type conforming to CustomDebugStringConvertible.
type DebugDescriber interface{ DebugDescription() string }

// SwiftNamed is a translated struct, class or enum that knows its qualified Swift type name.
type SwiftNamed interface{ SwiftTypeName() string }

// SwiftCase is an enum case: its Swift name and, for a case with a payload, the payload's labels.
type SwiftCase interface {
	SwiftCase() (name string, labels []string)
}

// Str renders a value the way Swift string interpolation and String(describing:) do.
func Str(v any) string { return describe(v, false) }

// StringInitReflecting is Swift `String(reflecting:)`.
func StringInitReflecting(v any) string { return describe(v, true) }

func debugStr(v any) string { return describe(v, true) }

// caseDescription is an enum case as Swift prints it: its name and payload, qualified by the
// enum's type when debug.
func caseDescription(v any, c SwiftCase, debug bool) string {
	name, labels := c.SwiftCase()
	s := name + payloadDescription(reflect.ValueOf(v), labels)
	if n, ok := v.(SwiftNamed); ok && debug {
		return n.SwiftTypeName() + "." + s
	}
	return s
}

func describe(v any, debug bool) string {
	if t, ok := v.(thrownValue); ok {
		// An `any Error` prints as the Swift value it holds.
		v = t.value
	}
	if rv := reflect.ValueOf(v); rv.Kind() == reflect.Pointer {
		// A pointer to a value type is an Optional. It has its pointee's methods, which must not be
		// called through it: nil is "nil", and a value prints as Optional(...).
		if _, class := v.(SwiftClass); !class {
			if rv.IsNil() {
				return "nil"
			}
			if _, named := rv.Elem().Interface().(SwiftNamed); named || rv.Elem().Kind() != reflect.Struct {
				return "Optional(" + debugStr(rv.Elem().Interface()) + ")"
			}
		} else if rv.IsNil() {
			return "nil"
		}
	}
	switch x := v.(type) {
	case nil:
		return "nil"
	case string:
		if debug {
			return swiftQuote(x)
		}
		return x
	case Substring:
		if debug {
			return swiftQuote(x.String())
		}
		return x.String()
	case DebugDescriber:
		if _, own := v.(ownDebugDescription); !own {
			if d, ok := v.(Describer); ok && !debug && !ownsDescription(v) {
				return d.Description()
			}
			return x.DebugDescription()
		}
		if d, ok := v.(Describer); ok && !ownsDescription(v) {
			return d.Description()
		}
		if c, ok := v.(SwiftCase); ok {
			return caseDescription(v, c, debug)
		}
	case Describer:
		if !ownsDescription(v) {
			return x.Description()
		}
		if c, ok := v.(SwiftCase); ok {
			return caseDescription(v, c, debug)
		}
	case fmt.Stringer:
		return x.String()
	case bool:
		return strconv.FormatBool(x)
	case int:
		return strconv.Itoa(x)
	case float64:
		return formatDouble(x)
	case float32:
		return swiftFloatDescription(float64(x), 32)
	case SwiftCase:
		return caseDescription(v, x, debug)
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Slice, reflect.Array:
		var s strings.Builder
		s.WriteString("[")
		for i := 0; i < rv.Len(); i++ {
			if i > 0 {
				s.WriteString(", ")
			}
			s.WriteString(debugStr(rv.Index(i).Interface()))
		}
		return s.String() + "]"
	case reflect.Map:
		return mapDescription(rv)
	case reflect.Pointer:
		if rv.IsNil() {
			return "nil"
		}
		if n, ok := v.(SwiftNamed); ok {
			if _, ok := v.(SwiftClass); ok {
				return n.SwiftTypeName()
			}
		}
		return "Optional(" + debugStr(rv.Elem().Interface()) + ")"
	case reflect.Struct:
		if n, ok := v.(SwiftNamed); ok {
			name := n.SwiftTypeName()
			if !debug {
				name = name[strings.LastIndexByte(name, '.')+1:]
			}
			return name + structFields(rv)
		}
		if rv.Type().Name() == "" {
			return tupleDescription(rv)
		}
	case reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return strconv.FormatInt(rv.Int(), 10)
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return strconv.FormatUint(rv.Uint(), 10)
	}
	return fmt.Sprint(v)
}

// payloadDescription is an enum case's payload as Swift prints it: `(by: "x", 2)`, or "" for none.
func payloadDescription(rv reflect.Value, labels []string) string {
	if rv.Kind() != reflect.Struct || rv.NumField() == 0 {
		return ""
	}
	var s strings.Builder
	s.WriteString("(")
	for i := range rv.NumField() {
		if i > 0 {
			s.WriteString(", ")
		}
		if i < len(labels) && labels[i] != "" {
			s.WriteString(labels[i] + ": ")
		}
		s.WriteString(debugStr(rv.Field(i).Interface()))
	}
	return s.String() + ")"
}

// structFields is a struct's stored properties as Swift prints them: `(a: 1, b: "x")`.
func structFields(rv reflect.Value) string {
	var s strings.Builder
	s.WriteString("(")
	first := true
	for i := range rv.NumField() {
		label, ok := rv.Type().Field(i).Tag.Lookup("swift")
		if !ok || !rv.Type().Field(i).IsExported() {
			continue
		}
		if !first {
			s.WriteString(", ")
		}
		first = false
		s.WriteString(label + ": " + debugStr(rv.Field(i).Interface()))
	}
	return s.String() + ")"
}

func tupleDescription(rv reflect.Value) string {
	var s strings.Builder
	s.WriteString("(")
	for i := range rv.NumField() {
		if i > 0 {
			s.WriteString(", ")
		}
		if rv.Type().Field(i).IsExported() {
			s.WriteString(debugStr(rv.Field(i).Interface()))
		}
	}
	return s.String() + ")"
}

// mapDescription is a Dictionary, or a Set held as a map to struct{}, as Swift prints it.
func mapDescription(rv reflect.Value) string {
	set := rv.Type().Elem().Kind() == reflect.Struct && rv.Type().Elem().NumField() == 0
	if rv.Len() == 0 {
		if set {
			return "[]"
		}
		return "[:]"
	}
	parts := make([]string, 0, rv.Len())
	for it := rv.MapRange(); it.Next(); {
		k := debugStr(it.Key().Interface())
		if set {
			parts = append(parts, k)
		} else {
			parts = append(parts, k+": "+debugStr(it.Value().Interface()))
		}
	}
	slices.Sort(parts)
	return "[" + strings.Join(parts, ", ") + "]"
}

// swiftQuote is String.debugDescription: the string in double quotes, with quotes, backslashes and
// ASCII control characters escaped.
func swiftQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case 0:
			b.WriteString(`\0`)
		case '\t':
			b.WriteString(`\t`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '"':
			b.WriteString(`\"`)
		case '\'':
			b.WriteString(`\'`)
		case '\\':
			b.WriteString(`\\`)
		default:
			if r < 0x20 || r == 0x7f {
				fmt.Fprintf(&b, `\u{%02X}`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

func formatDouble(f float64) string { return swiftFloatDescription(f, 64) }

// Is is Swift's `is`.
func Is[T any](v any) bool {
	_, ok := cast[T](v)
	return ok
}

// As is Swift's `as?`.
func As[T any](v any) *T {
	if t, ok := cast[T](v); ok {
		return &t
	}
	return nil
}

// AsRef is Swift's `as?` to a class or other reference type, whose optional Go represents as a
// nil-able T: the cast, or T's zero value. Unlike [As] it allocates nothing.
func AsRef[T any](v any) T {
	t, _ := cast[T](v)
	return t
}

// MustAs is Swift's `as!`. Casting to Any always succeeds, so a nil interface, which is how a Void
// result travels through a generic value such as a continuation's, becomes Any's zero value.
func MustAs[T any](v any) T {
	t, ok := cast[T](v)
	if !ok && v == nil && reflect.TypeFor[T]() == reflect.TypeFor[any]() {
		return t
	}
	if !ok {
		Trap(fmt.Sprintf("could not cast value of type %T", v))
	}
	return t
}

// cast is the dynamic cast of v to T that `is`, `as?` and `as!` share.
func cast[T any](v any) (T, bool) {
	if t, ok := v.(T); ok {
		return t, true
	}
	if t, ok, decided := classAs[T](v); decided {
		return t, ok
	}
	if t, ok := derefAs[T](v); ok {
		return t, true
	}
	if t, ok := bridgeAs[T](v); ok {
		return t, true
	}
	return collectionAs[T](v)
}

// Max is Swift's max(_:_:).
func Max[T cmp.Ordered](a, b T) T {
	if b >= a {
		return b
	}
	return a
}

// Min is Swift's min(_:_:).
func Min[T cmp.Ordered](a, b T) T {
	if b < a {
		return b
	}
	return a
}

// Same is Swift `===`: identity of two class references, either of which may be nil.
func Same(a, b any) bool {
	if isNil(a) || isNil(b) {
		return isNil(a) && isNil(b)
	}
	return Dynamic(a) == Dynamic(b)
}

// Dynamic returns the most-derived object behind a class reference that may be an embedded superclass.
func Dynamic(v any) any {
	if d, ok := v.(interface{ SwiftDynamic() any }); ok && !isNil(v) {
		return d.SwiftDynamic()
	}
	return v
}

// classAs matches the most-derived object behind a class reference against T, or one of its
// superclass parts when T is a class between the reference's static and dynamic types. decided is
// false when v is not a class reference; a class reference casts no other way.
func classAs[T any](v any) (t T, ok, decided bool) {
	c, isClass := v.(interface{ SwiftDynamic() any })
	if !isClass {
		return t, false, false
	}
	d := c.SwiftDynamic()
	if t, ok := d.(T); ok {
		return t, true, true
	}
	b, hasBases := d.(interface{ SwiftBase(i int) any })
	if !hasBases || isNil(d) {
		return t, false, true
	}
	for i := 0; ; i++ {
		p := b.SwiftBase(i)
		if p == nil {
			return t, false, true
		}
		if t, ok := p.(T); ok {
			return t, true, true
		}
	}
}

// Ref boxes a struct value for an existential whose methods need a pointer receiver.
func Ref[T any](v T) *T { return new(v) }

// derefAs matches v against T when v is a boxed *T.
func derefAs[T any](v any) (T, bool) {
	if p, ok := v.(*T); ok && p != nil {
		return *p, true
	}
	var zero T
	return zero, false
}

// CoalesceRef is Swift `??` on a class reference, which Go represents as a nil-able pointer.
func CoalesceRef[T any](p, d T) T {
	if isNil(p) {
		return d
	}
	return p
}

// CoalesceRefFunc is [CoalesceRef] with a right side that runs only when p is nil.
func CoalesceRefFunc[T any](p T, d func() T) T {
	if isNil(p) {
		return d()
	}
	return p
}

// CoalesceOpt is Swift `??` whose right side is itself optional.
func CoalesceOpt[T any](p, q T) T {
	if isNil(p) {
		return q
	}
	return p
}

// CoalesceOptFunc is [CoalesceOpt] with a right side that runs only when p is nil.
func CoalesceOptFunc[T any](p T, q func() T) T {
	if isNil(p) {
		return q()
	}
	return p
}

// Flat collapses a runtime optional of a class reference (**C) to the emitter's nil-able *C.
func Flat[T any](p *T) T {
	if p == nil {
		var zero T
		return zero
	}
	return *p
}

// UnitFn0 adapts a Void closure to a generic body that returns a value.
func UnitFn0(f func()) func() struct{} { return func() struct{} { f(); return struct{}{} } }

// UnitFn1 adapts a one-argument Void closure to a generic body that returns a value.
func UnitFn1[A any](f func(A)) func(A) struct{} {
	return func(a A) struct{} { f(a); return struct{}{} }
}

// UnitFn2 adapts a two-argument Void closure to a generic body that returns a value.
func UnitFn2[A, B any](f func(A, B)) func(A, B) struct{} {
	return func(a A, b B) struct{} { f(a, b); return struct{}{} }
}

// UnitFn3 adapts a three-argument Void closure to a generic body that returns a value.
func UnitFn3[A, B, C any](f func(A, B, C)) func(A, B, C) struct{} {
	return func(a A, b B, c C) struct{} { f(a, b, c); return struct{}{} }
}

// UnitFn4 adapts a four-argument Void closure to a generic body that returns a value.
func UnitFn4[A, B, C, D any](f func(A, B, C, D)) func(A, B, C, D) struct{} {
	return func(a A, b B, c C, d D) struct{} { f(a, b, c, d); return struct{}{} }
}

// AnyFn0 adapts a Void closure to a parameter whose generic result became `any`.
func AnyFn0(f func()) func() any { return func() any { f(); return nil } }

// AnyFn1 adapts a one-argument Void closure to a parameter whose generic result became `any`.
func AnyFn1[A any](f func(A)) func(A) any { return func(a A) any { f(a); return nil } }

// AnyFn2 adapts a two-argument Void closure to a parameter whose generic result became `any`.
func AnyFn2[A, B any](f func(A, B)) func(A, B) any { return func(a A, b B) any { f(a, b); return nil } }

// Eval returns v. Wrapping an operand in it makes Go read the operand before the calls to its
// right, as Swift does.
func Eval[T any](v T) T { return v }

// SwiftLesser is a type that declares its own `<`.
type SwiftLesser interface{ SwiftLess(other any) bool }

// Less is `a < b` on a type parameter that is only Comparable: Go's < for numbers and strings, and the type's
// own `<` otherwise.
func Less[T any](a, b T) bool {
	if l, ok := any(a).(SwiftLesser); ok {
		return l.SwiftLess(b)
	}
	va, vb := reflect.ValueOf(a), reflect.ValueOf(b)
	switch va.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return va.Int() < vb.Int()
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return va.Uint() < vb.Uint()
	case reflect.Float32, reflect.Float64:
		return va.Float() < vb.Float()
	case reflect.String:
		return va.String() < vb.String()
	}
	if sa, ok := any(a).(Substring); ok {
		return sa.String() < any(b).(Substring).String()
	}
	panic(fmt.Sprintf("swiftrt.Less: %T has no <", a))
}
